	rst_rounds_info ->> ''round_type_cd'' AS roundTypeCd,
	rst_rounds_info ->> ''reg_date_time'' AS regDateTime,
	rst_rounds_info ->> ''ind_user_id'' AS indUserId,
	(rst_rounds_info ->> ''ind_user_last_name'') || ''　'' ||(rst_rounds_info ->> ''ind_user_first_name'') AS indUserName,
	rst_rounds_info ->> ''reg_user_id'' AS regUserId,
	(rst_rounds_info ->> ''reg_user_last_name'') || ''　'' ||(rst_rounds_info ->> ''reg_user_first_name'') AS regUserName,
	case rst_rounds_info ->> ''is_ind_comment_post'' when ''0'' then ''転記しない'' else ''転記する'' end as isIndCommentPost,
	rst_rounds_info ->> ''ind_comment_no'' AS indCommentNo,
	case rst_rounds_info ->> ''posting_class'' when ''0'' then ''継続'' else ''当日のみ'' end as postingClass,
	rst_rounds_info ->> ''created_user_id'' AS createdUserId,
	(rst_rounds_info ->> ''created_user_last_name'') || ''　'' ||(rst_rounds_info ->> ''created_user_first_name'') AS createdUserName,
	rst_rounds_info ->> ''updated_user_id'' AS updated_user_id,
	(rst_rounds_info ->> ''updated_user_last_name'') || ''　'' ||(rst_rounds_info ->> ''updated_user_first_name'') AS updatedUserName
FROM
	ord_main 
WHERE
	ord_no = @ordNo 
	AND is_del = ''0'' 
